// n8n Code: Run Once for All Items.
// Расчёт календарных недель для Europe/Moscow (UTC+03:00).
const cfg = $input.first().json;
const repo = 'ramilEmazanov/RouteFinder';
const timezone = 'Europe/Moscow';
const dayMs = 24 * 60 * 60 * 1000;
const now = new Date();
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit',
}).formatToParts(now).map(p => [p.type, p.value]));
const today = `${parts.year}-${parts.month}-${parts.day}`;
const localMidnight = new Date(`${today}T00:00:00+03:00`);
const weekday = new Date(`${today}T00:00:00Z`).getUTCDay();
const thisMonday = new Date(localMidnight.getTime() - ((weekday + 6) % 7) * dayMs);
const override = String(cfg.test_week_start ?? '').trim();
let start = new Date(thisMonday.getTime() - 7 * dayMs);
if (override) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(override)) throw new Error('Use YYYY-MM-DD');
  start = new Date(`${override}T00:00:00+03:00`);
  const check = new Date(`${override}T00:00:00Z`);
  if (!Number.isFinite(start.getTime()) || check.toISOString().slice(0, 10) !== override
      || check.getUTCDay() !== 1) throw new Error('test_week_start must be a valid Monday');
  if (start > now) throw new Error('Test week cannot start in the future');
}
const end = new Date(start.getTime() + 7 * dayMs);
const localDate = value => new Date(value.getTime() + 3 * 60 * 60 * 1000).toISOString().slice(0, 10);
const weekStart = localDate(start);
const prevStart = localDate(new Date(start.getTime() - 7 * dayMs));
const secIso = value => value.toISOString().replace('.000Z', 'Z');
return [{ json: {
  repo, timezone,
  to_email: String(cfg.to_email ?? '').trim(),
  week_start: weekStart,
  week_end: localDate(end),
  last_day: localDate(new Date(end.getTime() - dayMs)),
  start_iso: secIso(start),
  end_iso: secIso(end),
  search_range: `${secIso(start)}..${secIso(new Date(end.getTime() - 1000))}`,
  week_key: `${repo}|${weekStart}`,
  previous_week_key: `${repo}|${prevStart}`,
  previous_week_start: prevStart,
  is_test: Boolean(override),
  is_partial: end > now,
  definition: 'Issues created in [start,end), open and closed, one classification label',
} }];

// n8n Code: Run Once for All Items. Имена HTTP-нод должны совпадать.
const p = $('Prepare Period').first().json;
const labels = ['bug', 'task', 'feature', 'needs-triage'];
const sources = ['Fetch Bug', 'Fetch Task', 'Fetch Feature', 'Fetch Triage'];
const issues = new Map();
for (const source of sources) {
  const pages = $(source).all().map(item => item.json);
  if (!pages.length) throw new Error(`${source}: no API response`);
  const sourceIds = new Set();
  let expected = 0;
  for (const page of pages) {
    if (!Array.isArray(page.items) || !Number.isInteger(page.total_count)
        || page.total_count < 0) throw new Error(`${source}: unexpected response`);
    if (page.incomplete_results !== false) throw new Error(`${source}: incomplete search`);
    expected = Math.max(expected, page.total_count);
    if (expected > 1000) throw new Error(`${source}: narrow the interval, GitHub search limit is 1000`);
    for (const issue of page.items) {
      sourceIds.add(issue.id);
      if (issue.pull_request) continue;
      const date = Date.parse(issue.created_at);
      if (!Number.isFinite(date)) throw new Error('Invalid issue created_at');
      if (date < Date.parse(p.start_iso) || date >= Date.parse(p.end_iso)) continue;
      const assigned = (issue.labels ?? []).map(l => typeof l === 'string' ? l : l.name)
        .filter(l => labels.includes(l));
      if (assigned.length !== 1) throw new Error(`Issue #${issue.number}: expected exactly one classification label`);
      issues.set(issue.id, {
        id: issue.id, number: issue.number, type: assigned[0],
        author: issue.user?.login ?? '(deleted)', url: issue.html_url,
      });
    }
  }
  if (sourceIds.size < expected) throw new Error(`${source}: missing pages or changing search results`);
}
const emptyCounts = () => Object.fromEntries(labels.map(k => [k, 0]));
const byType = emptyCounts();
const authors = new Map();
for (const issue of issues.values()) {
  byType[issue.type]++;
  if (!authors.has(issue.author)) authors.set(issue.author, { author: issue.author, total: 0, ...emptyCounts() });
  const row = authors.get(issue.author);
  row.total++;
  row[issue.type]++;
}
return [{ json: {
  ...p, schema_version: 1,
  total: issues.size, by_type: byType,
  by_author: [...authors.values()].sort((a,b) => b.total - a.total || a.author.localeCompare(b.author)),
  generated_at: new Date().toISOString(),
} }];

// n8n Code: Run Once for All Items. Письмо обычным текстом.
const r = $input.first().json;
const labels = ['bug', 'task', 'feature', 'needs-triage'];
const hasComparison = r.has_previous === true;
const formatDelta = value => value > 0 ? `+${value}` : String(value);
const metric = (name, current, previous, difference) => hasComparison
  ? `${name}: ${current} (прошлая неделя: ${previous}, Δ ${formatDelta(difference)})`
  : `${name}: ${current}`;

const lines = [
  'Недельный отчёт RouteFinder',
  `${r.week_start} — ${r.last_day}, ${r.timezone}`,
  '',
  'Классифицированные Issues, созданные за период. Учтены открытые и закрытые обращения.',
  '',
  metric('Всего', r.total, r.previous?.total, r.delta?.total),
  '',
  'По типам:',
  ...labels.map(label => metric(
    label, r.by_type[label], r.previous?.by_type?.[label], r.delta?.by_type?.[label],
  )),
];

if (r.has_previous === false) {
  lines.push('', 'Нет данных предыдущей недели для сравнения.');
}

lines.push('', 'По авторам:');
if (r.by_author.length) {
  for (const author of r.by_author) {
    lines.push(`${author.author}: всего ${author.total}; ${labels.map(label => `${label}: ${author[label]}`).join(', ')}`);
  }
} else {
  lines.push('За неделю обращений нет.');
}

if (r.ai_comment) {
  lines.push('', 'AI-комментарий недели:', String(r.ai_comment).trim());
}
lines.push('', 'Issues репозитория: https://github.com/ramilEmazanov/RouteFinder/issues');

return [{ json: {
  ...r,
  subject: `${r.is_test ? '[ТЕСТ] ' : ''}RouteFinder: Issues за ${r.week_start} — ${r.last_day}`,
  text: lines.join('\n'),
} }];

// n8n Code: Run Once for All Items. Вход от Get Previous Week (Always Output Data).
const current = $('Aggregate Stats').first().json;
const rows = $input.all().map(i => i.json).filter(row => row.week_key === current.previous_week_key);
if (rows.length > 1) throw new Error('Duplicate previous-week rows in Data Table');
if (!rows.length) return [{ json: { ...current, has_previous: false, previous: null, delta: null } }];
const previous = JSON.parse(rows[0].snapshot_json);
if (previous.schema_version !== current.schema_version
    || previous.week_key !== current.previous_week_key
    || previous.repo !== current.repo
    || previous.timezone !== current.timezone
    || previous.definition !== current.definition
    || previous.is_partial) throw new Error('Previous snapshot is incompatible or incomplete');
const labels = ['bug', 'task', 'feature', 'needs-triage'];
if (!Number.isInteger(previous.total) || previous.total < 0
    || labels.some(k => !Number.isInteger(previous.by_type?.[k]) || previous.by_type[k] < 0)
    || labels.reduce((s,k) => s + previous.by_type[k], 0) !== previous.total
    || !Array.isArray(previous.by_author)
    || previous.by_author.some(row => !Number.isInteger(row.total) || row.total < 0)
    || previous.by_author.reduce((s,row) => s + row.total, 0) !== previous.total) {
  throw new Error('Invalid previous snapshot counts');
}
const byType = Object.fromEntries(labels.map(k => [k, current.by_type[k] - previous.by_type[k]]));
const oldAuthors = new Map(previous.by_author.map(row => [row.author, row.total]));
const newAuthors = new Map(current.by_author.map(row => [row.author, row.total]));
const byAuthor = [...new Set([...oldAuthors.keys(), ...newAuthors.keys()])].sort().map(author => ({
  author, delta: (newAuthors.get(author) ?? 0) - (oldAuthors.get(author) ?? 0),
}));
return [{ json: {
  ...current, has_previous: true, previous,
  previous_is_test: previous.is_test === true,
  delta: { total: current.total - previous.total, by_type: byType, by_author: byAuthor },
} }];

// n8n Code: Run Once for All Items. Перед Data Table Upsert.
const r = $input.first().json;
const { to_email, previous, delta, has_previous, previous_is_test, ...snapshot } = r;
return [{ json: {
  week_key: r.week_key, repo: r.repo, week_start: r.week_start,
  week_end: r.week_end, timezone: r.timezone, total: r.total,
  is_test: r.is_test, snapshot_json: JSON.stringify(snapshot),
} }];

// n8n Code: Run Once for All Items. После Basic LLM Chain без Output Parser.
const r = $('Restore Report').first().json;
const answer = $input.first().json;
const comment = answer.text ?? answer.output;
if (typeof comment !== 'string' || !comment.trim()) throw new Error('AI annotation is empty');
return [{ json: { ...r, ai_comment: comment.trim() } }];
